´╗┐import { NextRequest, NextResponse } from "next/server";
import { createServiceSupabaseClient } from "@/lib/supabaseServer";

// Admin-only preview endpoint to locate rows containing a phone number across
// several tables/columns. Protect with ADMIN_API_KEY (header 'x-admin-key').
export async function POST(req: NextRequest) {
  const adminKey = process.env.ADMIN_API_KEY;
  if (adminKey) {
    const provided = req.headers.get("x-admin-key") || "";
    if (provided !== adminKey) return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  try {
      type PhonePreviewRequest = { phone?: string };
      const raw = await req.json() as unknown;
      if (typeof raw !== 'object' || raw === null) {
        return NextResponse.json({ error: 'invalid request body' }, { status: 400 });
      }
      const rawObj = raw as Record<string, unknown>;
      const phoneInput = typeof rawObj.phone === 'string' ? rawObj.phone : String(rawObj.phone ?? "");
      const phone = phoneInput.replace(/\D/g, "");

    // Candidate tables and columns to probe
    const tables = [
      "properties",
      "listings",
      "user_profiles",
      "pending_verifications",
      "visits",
      "contacts",
      "proposals",
      "messages",
    ];

    const phoneCols = [
      "phone",
      "celular",
      "celular_numero",
      "contact_phone",
      "owner_phone",
      "user_phone",
      "phone_number",
      "phone_normalized",
      "phone_normalized_digits",
      "telephone",
      "telefone",
      "mobile",
      "cel",
      "telefone_contato",
      // also try some generic fields that sometimes contain phone (but are not phones)
      "contact",
      "email",
      "full_name",
      "name",
      "title",
    ];

    // Build a set of LIKE patterns to try server-side. We query using ILIKE
    // to match stored strings that may include formatting characters.
    const patterns = new Set<string>();
    patterns.add(`%${phone}%`);
    // add suffix variations: last 8 and last 9 digits (common storage forms)
    if (phone.length > 8) patterns.add(`%${phone.slice(-8)}%`);
    if (phone.length > 9) patterns.add(`%${phone.slice(-9)}%`);

    const supabase = createServiceSupabaseClient();
    const result: Record<string, unknown> = {};

    // helper: try each column on a table and collect matches. Will attempt
    // each column and each pattern and avoid failing on missing columns.
    async function findMatches(tableName: string) {
      const found: Array<Record<string, unknown>> = [];
      for (const col of phoneCols) {
        try {
          for (const p of Array.from(patterns)) {
            // Try to select the column and id; if column doesn't exist supabase returns an error
            const { data, error } = await supabase.from(tableName).select(`id, ${col}`).ilike(col, p).limit(500);
            if (error) {
              // likely the column doesn't exist or incompatible type; stop trying this column
              break;
            }
            if (data && data.length > 0) {
              for (const r of data) {
                // Normalize the candidate value server-side in JS and ensure the digits match
                const row = r as Record<string, unknown>;
                const rawVal = row[col as string];
                const val = (typeof rawVal === 'string' || typeof rawVal === 'number') ? String(rawVal) : "";
                const digits = val.replace(/\D/g, "");
                if (digits && (digits.includes(phone) || phone.includes(digits) || digits.endsWith(phone.slice(-8)))) {
                  // attach entire row object for inspection
                  const rid = String(row['id'] ?? "");
                  const _exists = found.find((f) => String(f['id']) === rid);
                  if (!_exists) found.push({ id: rid, column: col, value: val, row });
                }
              }
            }
          }
        } catch {
          // ignore and continue with next column
          continue;
        }
      }
      return found;
    }

    for (const t of tables) {
      try {
        const matches = await findMatches(t);
        result[t] = { count: matches.length, rows: matches };
      } catch (err) {
        result[t] = { error: String(err), count: 0, rows: [] };
      }
    }

    return NextResponse.json({ ok: true, phone: phone, result });
    } catch (err: unknown) {
    const msg = (err && typeof err === 'object' && 'message' in err) ? String(((err as unknown) as Record<string, unknown>)['message']) : String(err);
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createServerSupabaseClient, createServiceSupabaseClient } from '@/lib/supabaseServer';
import { randomUUID } from 'crypto';

// Proxy for in-app admin UI to upload property media (photos/videos) and optional KML
// Requires session-auth and admin email allowlist (reads app_settings.admin_emails)

async function ensureAdmin() {
  const serverSupabase = createServerSupabaseClient();
  const { data } = await serverSupabase.auth.getUser();
  const user = data?.user;
  if (!user || !user.email) return { ok: false };
  const email = user.email.toLowerCase();

  try {
    const svc = createServiceSupabaseClient();
    const { data: setting } = await svc.from('app_settings').select('value').eq('key', 'admin_emails').maybeSingle();
    if (setting?.value) {
      const list = Array.isArray(setting.value) ? setting.value : JSON.parse(setting.value);
      const normalized = list.map((e: unknown) => String(e).toLowerCase());
      if (normalized.includes(email)) return { ok: true, user };
    }
  } catch (err) {
    console.error('property-media proxy: failed to read admin_emails', err);
  }

  // fallback hard-coded check
  const FALLBACK = ['admin@publimicro.com.br', 'contato@publimicro.com.br'];
  if (FALLBACK.includes(email)) return { ok: true, user };
  return { ok: false };
}

export async function POST(req: NextRequest) {
  const auth = await ensureAdmin();
  if (!auth.ok) return NextResponse.json({ error: 'Forbidden' }, { status: 403 });

  try {
    type FilePayload = { name?: string; base64?: string; mime?: string; thumbnail?: string };
    type KmlPayload = { name?: string; base64?: string; mime?: string };
    type UploadResult = { name: string; publicUrl?: string; path?: string; thumbnail?: string | null; error?: string; placeholderId?: string };

    const raw = await req.json() as unknown;
    if (typeof raw !== 'object' || raw === null) {
      return NextResponse.json({ error: 'invalid request body' }, { status: 400 });
    }
    const body = raw as Record<string, unknown>;
    const propertyId = String(body.property_id ?? "").trim();
    const files = Array.isArray(body.files) ? (body.files as Array<unknown>) : [];
    const kml = (body.kmlFile && typeof body.kmlFile === 'object') ? (body.kmlFile as Record<string, unknown>) : undefined;

    if (!propertyId) return NextResponse.json({ error: 'property_id is required' }, { status: 400 });

    const svc = createServiceSupabaseClient();
    const uploads: UploadResult[] = [];

    // Upload files to bucket 'property-photos'
    for (const rawF of files) {
      try {
        const f = (rawF as Record<string, unknown>) || {};
        const folder = `properties/${propertyId}`;
        const fname = String(f.name ?? 'file');
        const name = `${folder}/${Date.now()}_${Math.random().toString(36).slice(2,8)}_${fname}`;
        const base64 = String(f.base64 ?? '');
        const buffer = Buffer.from(base64, 'base64');
        const contentType = String(f.mime ?? 'application/octet-stream');
        const { error: upErr } = await svc.storage.from('property-photos').upload(name, buffer, { contentType, upsert: false });
        if (upErr) {
          const upErrMsg = upErr && typeof upErr === 'object' && 'message' in upErr ? String((upErr as Record<string, unknown>)['message']) : String(upErr);
          uploads.push({ name: fname, error: upErrMsg });
          continue;
        }
        const { data } = svc.storage.from('property-photos').getPublicUrl(name);
        const publicUrl = data && typeof data === 'object' && 'publicUrl' in data ? String((data as Record<string, unknown>)['publicUrl']) : undefined;
        uploads.push({ name: fname, publicUrl, path: name, thumbnail: (f.thumbnail as string) || null });
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        uploads.push({ name: String((rawF as any)?.name ?? 'file'), error: msg });
      }
    }

    let kmlPublicUrl: string | null = null;
    if (kml && typeof kml.base64 === 'string') {
      try {
        const kmlPayload: KmlPayload = { name: String(kml.name ?? 'map.kml'), base64: String(kml.base64), mime: String(kml.mime ?? 'application/vnd.google-earth.kml+xml') };
        const kname = kmlPayload.name;
        const name = `properties/${propertyId}/kml_${Date.now()}_${Math.random().toString(36).slice(2,8)}_${kname}`;
        const buffer = Buffer.from(kmlPayload.base64, 'base64');
        const contentType = kmlPayload.mime;
        const { error: kErr } = await svc.storage.from('property-photos').upload(name, buffer, { contentType, upsert: false });
        if (!kErr) {
          const { data } = svc.storage.from('property-photos').getPublicUrl(name);
          kmlPublicUrl = data && typeof data === 'object' && 'publicUrl' in data ? String((data as Record<string, unknown>)['publicUrl']) : null;
        } else {
          const kErrMsg = kErr && typeof kErr === 'object' && 'message' in kErr ? String((kErr as Record<string, unknown>)['message']) : String(kErr);
          uploads.push({ name: kname, error: kErrMsg });
        }
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        uploads.push({ name: String(kml?.name ?? 'map.kml'), error: msg });
      }
    }

    // Insert into unified media table when feature flag enabled, otherwise legacy property_photos
    const USE_PLACEHOLDERS = process.env.FEATURE_MEDIA_PLACEHOLDERS === 'true';
    const successful = uploads.filter((u): u is Record<string, unknown> & { publicUrl: string } => typeof u.publicUrl === 'string');
    for (let i = 0; i < successful.length; i++) {
      const u = successful[i];
      try {
        if (USE_PLACEHOLDERS) {
          const placeholderId = randomUUID();
          await svc.from('media').insert({
            resource_type: 'property',
            resource_id: propertyId,
            placeholder_id: placeholderId,
            url: u.publicUrl,
            thumbnail_url: (u.thumbnail as string) || null,
            caption_pt: (u.name as string) || null,
            status: 'processing',
            display_order: i,
            is_cover: i === 0
          });
          u.placeholderId = placeholderId;
        } else {
          await svc.from('property_photos').insert({ property_id: propertyId, url: u.publicUrl, thumbnail_url: null, caption: (u.name as string) || null, display_order: 0, is_cover: false });
        }
      } catch (err) {
        console.error('Failed to insert property_photos/media row', err);
      }
    }

    // Update sitios.kml_url if kmlPublicUrl present
    if (kmlPublicUrl) {
      try {
        await svc.from('sitios').update({ kml_url: kmlPublicUrl }).eq('id', propertyId);
      } catch (err) {
        console.error('Failed to update sitios.kml_url', err);
      }
    }

    // Write audit record
    try {
      const changedBy = (auth.user && (auth.user.email || auth.user.id)) || null;
      await svc.from('property_media_audit').insert({ property_id: propertyId, uploads: uploads, changed_by: changedBy });
    } catch (e: unknown) {
      console.error('Failed to write property_media_audit', e instanceof Error ? e.message : String(e));
    }

    return NextResponse.json({ ok: true, uploads, kml_url: kmlPublicUrl });
  } catch (e: unknown) {
    console.error('property-media proxy error', e instanceof Error ? e.message : String(e));
    const msg = e instanceof Error ? e.message : String(e);
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createServiceSupabaseClient } from '@/lib/supabaseServer';
import { randomUUID } from 'crypto';

const ADMIN_HEADER = 'x-admin-key';
const DEFAULT_MAX_BYTES = 50 * 1024 * 1024; // 50 MB
const DEFAULT_MAX_FILES = 20;
const ALLOWED_MIMES = [
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/heic',
  'image/avif',
  'video/mp4',
  'video/quicktime',
  'application/vnd.google-earth.kml+xml',
  'application/xml',
  'text/xml'
];

function sanitizeFileName(name: string) {
  return (name || 'file').replace(/[^a-zA-Z0-9-_.]/g, '_').slice(0, 180);
}

function isMimeAllowed(mime?: string) {
  if (!mime) return false;
  return ALLOWED_MIMES.includes(mime.toLowerCase());
}

export async function POST(req: NextRequest) {
  const adminKey = process.env.ADMIN_API_KEY;
  if (!adminKey) return NextResponse.json({ error: 'ADMIN_API_KEY not configured' }, { status: 500 });
  const provided = req.headers.get(ADMIN_HEADER) || '';
  if (provided !== adminKey) return NextResponse.json({ error: 'Forbidden' }, { status: 403 });

  const MAX_BYTES = Number(process.env.ADMIN_MAX_UPLOAD_BYTES || DEFAULT_MAX_BYTES);
  const MAX_FILES = Number(process.env.ADMIN_MAX_UPLOAD_FILES || DEFAULT_MAX_FILES);

  try {
    type FilePayload = { name?: string; base64?: string; mime?: string };
    type KmlPayload = { name?: string; base64?: string; mime?: string };
    type UploadResult = { name: string; publicUrl?: string; path?: string; error?: string };

    const raw = await req.json() as unknown;
    if (typeof raw !== 'object' || raw === null) {
      return NextResponse.json({ error: 'invalid request body' }, { status: 400 });
    }
    const body = raw as Record<string, unknown>;
    const propertyId = String(body.property_id ?? "").trim();
    const files = Array.isArray(body.files) ? (body.files as Array<unknown>) : [];
    const kml = (body.kmlFile && typeof body.kmlFile === 'object') ? (body.kmlFile as Record<string, unknown>) : undefined;

    if (!propertyId) return NextResponse.json({ error: 'property_id is required' }, { status: 400 });
    if (files.length + (kml ? 1 : 0) > MAX_FILES) return NextResponse.json({ error: `Too many files (max ${MAX_FILES})` }, { status: 400 });

    const svc = createServiceSupabaseClient();
    const uploads: Array<Record<string, unknown>> = [];

    for (const rawF of files) {
      const f = (rawF as Record<string, unknown>) || {};
      const nameRaw = String(f.name ?? 'file');
      const mime = String(f.mime ?? '').toLowerCase();
      if (!isMimeAllowed(mime)) {
        uploads.push({ name: nameRaw, error: 'MIME type not allowed' });
        continue;
      }

      // Quick size check using base64 length when available
      const base64 = String(f.base64 ?? '');
      const estimatedBytes = Math.floor((base64.length * 3) / 4);
      if (estimatedBytes > MAX_BYTES) {
        uploads.push({ name: nameRaw, error: `File exceeds max size of ${Math.round(MAX_BYTES / (1024 * 1024))}MB` });
        continue;
      }

      try {
        const folder = `properties/${String(propertyId)}`;
        const fileName = `${Date.now()}_${Math.random().toString(36).slice(2,8)}_${sanitizeFileName(nameRaw)}`;
        const path = `${folder}/${fileName}`;
        const buffer = Buffer.from(base64, 'base64');
        const { error: upErr } = await svc.storage.from('property-photos').upload(path, buffer, { contentType: mime || 'application/octet-stream', upsert: false });
        if (upErr) {
          const upErrMsg = upErr && typeof upErr === 'object' && 'message' in upErr ? String((upErr as Record<string, unknown>)['message']) : String(upErr);
          uploads.push({ name: nameRaw, error: upErrMsg });
          continue;
        }
        const { data } = svc.storage.from('property-photos').getPublicUrl(path);
        const publicUrl = data && typeof data === 'object' && 'publicUrl' in data ? String((data as Record<string, unknown>)['publicUrl']) : undefined;
        uploads.push({ name: nameRaw, publicUrl, path });
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        uploads.push({ name: nameRaw, error: msg });
      }
    }

    let kmlPublicUrl: string | null = null;
    if (kml && typeof (kml as Record<string, unknown>).base64 === 'string') {
      const kmlNameRaw = String((kml as Record<string, unknown>)?.name ?? 'map.kml');
      const kmlMime = String((kml as Record<string, unknown>)?.mime ?? 'application/vnd.google-earth.kml+xml');
      if (!isMimeAllowed(kmlMime)) {
        uploads.push({ name: kmlNameRaw, error: 'KML MIME type not allowed' });
      } else {
        const base64 = String((kml as Record<string, unknown>)?.base64 ?? '');
        const estimatedBytes = Math.floor((base64.length * 3) / 4);
        if (estimatedBytes > MAX_BYTES) {
          uploads.push({ name: kmlNameRaw, error: `KML file exceeds max size of ${Math.round(MAX_BYTES / (1024 * 1024))}MB` });
        } else {
          try {
            const name = `properties/${String(propertyId)}/kml_${Date.now()}_${Math.random().toString(36).slice(2,8)}_${sanitizeFileName(kmlNameRaw)}`;
            const buffer = Buffer.from(base64, 'base64');
            const { error: kErr } = await svc.storage.from('property-photos').upload(name, buffer, { contentType: kmlMime, upsert: false });
              if (!kErr) {
                const { data } = svc.storage.from('property-photos').getPublicUrl(name);
                kmlPublicUrl = data && typeof data === 'object' && 'publicUrl' in data ? String((data as Record<string, unknown>)['publicUrl']) : null;
              } else {
                const kErrMsg = kErr && typeof kErr === 'object' && 'message' in kErr ? String(((kErr as unknown) as Record<string, unknown>)['message']) : String(kErr);
                uploads.push({ name: kmlNameRaw, error: kErrMsg });
              }
          } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            uploads.push({ name: kmlNameRaw, error: msg });
          }
        }
      }
    }

    const USE_PLACEHOLDERS = process.env.FEATURE_MEDIA_PLACEHOLDERS === 'true';
    const successful = uploads.filter((u): u is Record<string, unknown> & { publicUrl: string } => typeof u.publicUrl === 'string');
    for (const u of successful) {
      try {
        if (USE_PLACEHOLDERS) {
          const placeholderId = randomUUID();
          await svc.from('media').insert({
            resource_type: 'property',
            resource_id: propertyId,
            placeholder_id: placeholderId,
            url: u.publicUrl,
            thumbnail_url: (u.thumbnail as string) || null,
            caption_pt: (u.name as string) || null,
            status: 'processing',
            display_order: 0,
            is_cover: false
          });
          u.placeholderId = placeholderId;
        } else {
          await svc.from('property_photos').insert({ property_id: propertyId, url: u.publicUrl, thumbnail_url: null, caption: (u.name as string) || null, display_order: 0, is_cover: false });
        }
      } catch (err) {
        console.error('Failed to insert property_photos/media row', err);
      }
    }

    if (kmlPublicUrl) {
      try { await svc.from('sitios').update({ kml_url: kmlPublicUrl }).eq('id', propertyId); } catch (err) { console.error('Failed to update sitios.kml_url', err); }
    }

    try { await svc.from('property_media_audit').insert({ property_id: propertyId, uploads, changed_by: req.headers.get('x-admin-user') || 'admin-api' }); } catch (e: unknown) { console.error('Failed to write property_media_audit', e instanceof Error ? e.message : String(e)); }

    return NextResponse.json({ ok: true, uploads, kml_url: kmlPublicUrl });
  } catch (e: unknown) {
    console.error('property-media admin error', e instanceof Error ? e.message : String(e));
    const msg = e instanceof Error ? e.message : String(e);
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createServerSupabaseClient } from '@/lib/supabaseServer';

/**
 * Background Check API
 * Performs Federal Police and Interpol checks
 * INTERNAL USE ONLY - Called by server-side processes
 */

interface BackgroundCheckRequest {
  cpf: string;
  full_name: string;
  birth_date?: string;
  email?: string;
  pending_verification_id?: string;
  cidade?: string;
  estado?: string;
}

interface ExternalCheckResponse {
  [k: string]: unknown;
  has_criminal_record?: boolean;
  is_wanted?: boolean;
  is_red_notice?: boolean;
  restrictions?: unknown[];
  checked_at?: string;
}

export async function POST(req: Request) {
  const supabase = createServerSupabaseClient();
  
  try {
    const raw = await req.json() as unknown;
    if (typeof raw !== 'object' || raw === null) {
      return NextResponse.json({ error: 'invalid request body' }, { status: 400 });
    }
    const body = raw as Record<string, unknown>;
    const cpf = String(body.cpf ?? "").trim();
    const full_name = String(body.full_name ?? "").trim();
    const birth_date = body.birth_date ? String(body.birth_date) : undefined;
    const email = body.email ? String(body.email) : undefined;
    const pending_verification_id = body.pending_verification_id ? String(body.pending_verification_id) : undefined;
    const cidade = body.cidade ? String(body.cidade) : undefined;
    const estado = body.estado ? String(body.estado) : undefined;

    if (!cpf || !full_name) {
      return NextResponse.json({ error: 'CPF and full name are required' }, { status: 400 });
    }

    const cleanCPF = cpf.replace(/\D/g, '');
    
    // ============================================
    // 1. Federal Police Check (Pol├¡cia Federal)
    // ============================================
    
    let federalPoliceStatus: 'approved' | 'rejected' | 'needs_review' = 'approved';
    let federalPoliceResponse: ExternalCheckResponse | null = null;
    
    try {
      // TODO: Integration with Brazilian Federal Police API
      // Endpoint: https://servicos.dpf.gov.br/api/antecedentes
      // This would check for:
      // - Criminal records
      // - Wanted persons
      // - Restrictions
      
      // Simulated API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      federalPoliceResponse = {
        cpf: cleanCPF,
        name: full_name,
        has_criminal_record: false,
        is_wanted: false,
        restrictions: [],
        checked_at: new Date().toISOString()
      };
      
      // Log Federal Police check
      await supabase.from('verification_logs').insert({
        user_id: null,
        verification_type: 'federal_police',
        status: federalPoliceStatus,
        request_data: { cpf: cleanCPF, full_name, birth_date },
        response_data: federalPoliceResponse
      });
      
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      console.error('Federal Police check error:', msg);
      federalPoliceStatus = 'needs_review';
      federalPoliceResponse = { error: msg };
    }
    
    // ============================================
    // 2. Interpol Check (International Database)
    // ============================================
    
    let interpolStatus: 'approved' | 'rejected' | 'needs_review' = 'approved';
    let interpolResponse: ExternalCheckResponse | null = null;
    
    try {
      // TODO: Integration with Interpol I-24/7 Database
      // Note: This requires special authorization from Interpol
      // Alternative: Use third-party services like:
      // - WorldCheck (Refinitiv)
      // - ComplyAdvantage
      // - Dow Jones Risk & Compliance
      
      // Simulated API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      interpolResponse = {
        name: full_name,
        is_red_notice: false,
        is_wanted: false,
        travel_restrictions: [],
        checked_at: new Date().toISOString()
      };
      
      // Log Interpol check
      await supabase.from('verification_logs').insert({
        user_id: null,
        verification_type: 'interpol',
        status: interpolStatus,
        request_data: { full_name, birth_date },
        response_data: interpolResponse
      });
      
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      console.error('Interpol check error:', msg);
      interpolStatus = 'needs_review';
      interpolResponse = { error: msg };
    }
    
    // ============================================
    // 3. Determine Overall Result (auto/manual/alert)
    // ============================================
    let finalStatus: 'approved' | 'rejected' | 'needs_review';
    let rejectionReason: string | null = null;
    let policeAlert: boolean = false;

    // If any criminal/wanted/red notice, auto-reject and alert
    const isCriminal =
      (federalPoliceResponse?.has_criminal_record === true) ||
      (federalPoliceResponse?.is_wanted === true) ||
      (interpolResponse?.is_red_notice === true) ||
      (interpolResponse?.is_wanted === true);

    if (isCriminal) {
      finalStatus = 'rejected';
      rejectionReason = 'Criminal or wanted status detected. Alert sent to authorities.';
      policeAlert = true;
      // Integrate with police alert system (placeholder)
      const alertPayload = {
        cpf: cleanCPF,
        full_name,
        birth_date,
        email,
        cidade,
        estado,
        federalPoliceResponse,
        interpolResponse,
        timestamp: new Date().toISOString(),
      };
      // TODO: Replace with real police alert integration (email, webhook, etc.)
      // await fetch('https://api.police-alert.local/alert', { method: 'POST', body: JSON.stringify(alertPayload) });
      await supabase.from('verification_logs').insert({
        user_id: null,
        verification_type: 'police_alert',
        status: 'alerted',
        request_data: alertPayload,
        response_data: { sent: false, reason: 'Integration not implemented' }
      });
    } else if (
      String(federalPoliceStatus) === 'rejected' ||
      String(interpolStatus) === 'rejected'
    ) {
      finalStatus = 'rejected';
      rejectionReason = 'Background check failed: status rejected by authority.';
    } else if (
      federalPoliceStatus === 'needs_review' ||
      interpolStatus === 'needs_review'
    ) {
      finalStatus = 'needs_review';
      rejectionReason = 'Manual review required: unable to determine status automatically.';
    } else {
      finalStatus = 'approved';
    }
    
    // ============================================
    // 4. Update Pending Verification Record
    // ============================================
    
    if (pending_verification_id) {
      await supabase
        .from('pending_verifications')
        .update({
          federal_police_check_status: federalPoliceStatus,
          federal_police_check_date: new Date().toISOString(),
          federal_police_response: federalPoliceResponse,
          interpol_check_status: interpolStatus,
          interpol_check_date: new Date().toISOString(),
          interpol_response: interpolResponse,
          verification_status: finalStatus,
          // Set verified_at only when explicitly approved
          verified_at: finalStatus === 'approved' ? new Date().toISOString() : null,
          verification_passed: finalStatus === 'approved',
          rejection_reason: rejectionReason,
          police_alert: policeAlert
        })
        .eq('id', pending_verification_id);
    }
    
    // ============================================
    // 5. Return Results
    // ============================================
    
    return NextResponse.json({
      status: finalStatus,
      police_alert: policeAlert,
      rejection_reason: rejectionReason,
      checks: {
        federal_police: {
          status: federalPoliceStatus,
          response: federalPoliceResponse
        },
        interpol: {
          status: interpolStatus,
          response: interpolResponse
        }
      },
      checked_at: new Date().toISOString()
    });
    
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      console.error('Background check error:', msg);
      return NextResponse.json({
        error: msg || 'Background check failed'
      }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { getStripe, STRIPE_PRICES } from "@/lib/stripe";
import { createClient } from "@supabase/supabase-js";

export async function POST(req: Request) {
  try {
    const { listingId, productType } = await req.json();

    if (!listingId || !productType) {
      return NextResponse.json(
        { error: "Listing ID e tipo de produto s├úo obrigat├│rios" },
        { status: 400 }
      );
    }

    // Pegar token de autentica├º├úo do header
    const authHeader = req.headers.get("authorization");
    const token = authHeader?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { error: "Token de autentica├º├úo ausente" },
        { status: 401 }
      );
    }

    // Criar cliente Supabase com o token do usu├írio
    const supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
      {
        global: {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      }
    );

    // Verificar autentica├º├úo
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json(
        { error: "Usu├írio n├úo autenticado" },
        { status: 401 }
      );
    }

    // ============================================
    // VERIFICA├ç├âO DE IDENTIDADE OBRIGAT├ôRIA
    // ============================================
    // Check if user is verified before allowing premium purchases
    const { data: profile, error: profileError } = await supabase
      .from("user_profiles")
      .select("verification_status")
      .eq("user_id", user.id)
      .single();

    if (profileError) {
      console.error("Error fetching user profile:", profileError);
      return NextResponse.json(
        { error: "Erro ao verificar perfil do usu├írio" },
        { status: 500 }
      );
    }

    // Require verification for premium features
    if (profile?.verification_status !== "approved") {
      return NextResponse.json(
        { 
          error: "Verifica├º├úo de identidade necess├íria",
          requiresVerification: true,
          verificationStatus: profile?.verification_status || "not_started"
        },
        { status: 403 }
      );
    }

    // Verificar se o listing existe e pertence ao usu├írio
    const { data: listing, error: listingError } = await supabase
      .from("listings")
      .select("id, title, user_id")
      .eq("id", listingId)
      .single();

    if (listingError || !listing) {
      return NextResponse.json(
        { error: "An├║ncio n├úo encontrado" },
        { status: 404 }
      );
    }

    if (listing.user_id !== user.id) {
      return NextResponse.json(
        { error: "Voc├¬ n├úo tem permiss├úo para modificar este an├║ncio" },
        { status: 403 }
      );
    }

    // Selecionar o pre├ºo correto
    const priceId =
      productType === "destaque"
        ? STRIPE_PRICES.DESTAQUE
        : STRIPE_PRICES.MARKETING;

    if (!priceId) {
      return NextResponse.json(
        { error: "Price ID n├úo configurado" },
        { status: 500 }
      );
    }

    // Criar sess├úo de checkout do Stripe
    const stripe = getStripe();
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"], // Pix ser├í adicionado depois
      line_items: [
        {
          price: priceId,
          quantity: 1,
        },
      ],
      mode: "payment",
      success_url: `${process.env.NEXT_PUBLIC_URL || "http://localhost:3000"}/acheme-coisas/publicado?id=${listingId}&payment=success`,
      cancel_url: `${process.env.NEXT_PUBLIC_URL || "http://localhost:3000"}/acheme-coisas/publicado?id=${listingId}&payment=cancelled`,
      metadata: {
        listingId,
        userId: user.id,
        productType,
        listingTitle: listing.title,
      },
      customer_email: user.email,
    });

    return NextResponse.json({ url: session.url });
  } catch (error) {
    const message = error && typeof error === 'object' && 'message' in error ? (error as { message?: string }).message : String(error);
    console.error("Erro ao criar sess├úo de checkout:", message);
    return NextResponse.json(
      { error: message || "Erro ao criar sess├úo de pagamento" },
      { status: 500 }
    );
  }
}

