/**
 * Get tier by ID
 */
export function getTierById(tierId: string): ListingTier | undefined {
  return LISTING_TIERS.find(tier => tier.id === tierId);
}

/**
 * Get tier limits by ID
 */
export function getTierLimits(tierId: string): ListingTierLimits | undefined {
  return getTierById(tierId)?.limits;
}

/**
 * Check if user can post free listing
 * Returns true if user hasn't used their free listing yet
 */
import type { SupabaseClient } from '@supabase/supabase-js';

export async function canPostFreeListing(userId: string, supabase: SupabaseClient): Promise<boolean> {
  const { count, error } = await supabase
    .from('listings')
    .select('*', { count: 'exact', head: true })
    .eq('user_id', userId)
    .eq('tier', 'free') as unknown as { count?: number | null; error?: any };
  
  if (error) {
    console.error('Error checking free listing:', error);
    return false;
  }
  
  return (count || 0) < 1; // Allow only 1 free listing per user
}

/**
 * Validate photo count for tier
 */
export function validatePhotoCount(photos: number, tierId: string): { valid: boolean; message?: string } {
  const limits = getTierLimits(tierId);
  if (!limits) return { valid: false, message: 'Plano inv├ílido' };
  
  if (photos < limits.minPhotos) {
    return { 
      valid: false, 
      message: `M├¡nimo de ${limits.minPhotos} foto${limits.minPhotos > 1 ? 's' : ''} necess├íria${limits.minPhotos > 1 ? 's' : ''}` 
    };
  }
  
  if (photos > limits.maxPhotos) {
    return { 
      valid: false, 
      message: `M├íximo de ${limits.maxPhotos} fotos permitidas no plano ${getTierById(tierId)?.name}` 
    };
  }
  
  return { valid: true };
}

/**
 * Validate video for tier
 */
export function validateVideo(
  videoCount: number, 
  videoSizeMB: number, 
  videoDurationSeconds: number, 
  tierId: string
): { valid: boolean; message?: string } {
  const limits = getTierLimits(tierId);
  if (!limits) return { valid: false, message: 'Plano inv├ílido' };
  
  if (videoCount > limits.maxVideos) {
    if (limits.maxVideos === 0) {
      return { valid: false, message: 'V├¡deos n├úo s├úo permitidos no plano gratuito' };
    }
    return { 
      valid: false, 
      message: `M├íximo de ${limits.maxVideos} v├¡deo${limits.maxVideos > 1 ? 's' : ''} permitido${limits.maxVideos > 1 ? 's' : ''} no plano ${getTierById(tierId)?.name}` 
    };
  }
  
  if (videoSizeMB > limits.maxVideoSizeMB) {
    return { 
      valid: false, 
      message: `Tamanho m├íximo do v├¡deo: ${limits.maxVideoSizeMB}MB no plano ${getTierById(tierId)?.name}` 
    };
  }
  
  if (videoDurationSeconds > limits.maxVideoDurationSeconds) {
    const maxMinutes = Math.floor(limits.maxVideoDurationSeconds / 60);
    return { 
      valid: false, 
      message: `Dura├º├úo m├íxima do v├¡deo: ${maxMinutes} minuto${maxMinutes > 1 ? 's' : ''} no plano ${getTierById(tierId)?.name}` 
    };
  }
  
  return { valid: true };
}

